-- ============================================================
-- Ratings & Insights: outlet_master schema migration
-- Generated from Swiggy Resid sheet (2946 rows)
-- ============================================================

-- STEP 0 (READ-ONLY, run first): check for existing duplicate
-- restaurant_ids already in outlet_master. If this returns any rows,
-- STOP and resolve them manually before running STEP 3 (the UNIQUE
-- constraint on restaurant_id will fail otherwise).
SELECT restaurant_id, COUNT(*) FROM outlet_master GROUP BY restaurant_id HAVING COUNT(*) > 1;

-- STEP 0b (READ-ONLY, informational): order_reviews rows whose
-- restaurant_id has no match in outlet_master. These permanently lose
-- area/kitchen info once order_reviews.area is dropped in STEP 2.
SELECT COUNT(*) AS orphaned_reviews
FROM order_reviews r
LEFT JOIN outlet_master o ON o.restaurant_id = r.restaurant_id
WHERE o.restaurant_id IS NULL;

-- STEP 1: add sub_brand column, rename area -> kitchen, drop business_entity
ALTER TABLE outlet_master ADD COLUMN IF NOT EXISTS sub_brand TEXT;
ALTER TABLE outlet_master RENAME COLUMN area TO kitchen;
ALTER TABLE outlet_master DROP COLUMN IF EXISTS business_entity;

-- STEP 2: drop area from order_reviews (kitchen/area info now comes
-- solely from outlet_master via restaurant_id)
ALTER TABLE order_reviews DROP COLUMN IF EXISTS area;

-- STEP 3: drop the old composite constraint and make restaurant_id
-- alone unique. Every restaurant_id in the Swiggy Resid sheet was
-- unique (verified: 2946 rows, 0 duplicate IDs), and kitchen
-- is now sourced from this reference sheet per restaurant_id, not
-- from the daily report -- so (restaurant_id, area) no longer makes
-- sense as the identity. Only run this after STEP 0 comes back empty.
ALTER TABLE outlet_master DROP CONSTRAINT IF EXISTS outlet_master_restaurant_id_area_key;
ALTER TABLE outlet_master ADD CONSTRAINT outlet_master_restaurant_id_key UNIQUE (restaurant_id);

-- STEP 4: upsert all 2946 outlets from the Swiggy Resid sheet.
-- Existing restaurant_ids get brand_name/sub_brand/city/kitchen/zone
-- OVERWRITTEN with the sheet's values (including for outlets that
-- already have historical order_reviews data). New restaurant_ids get
-- inserted.

